// Validate the webhook body: { "batch_id": "<uuid>", "valid_rows": <int> }.
// batch_id is later placed into SQL, so anything that is not a UUID is rejected here.
const body = $input.first().json.body ?? {};
const batchId = String(body.batch_id ?? '').trim().toLowerCase();
const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(batchId);

return [{
  json: {
    valid: isUuid,
    batch_id: batchId,
    started_at: Date.now(),
    error: isUuid ? null : 'batch_id must be a UUID',
  },
}];

// Stage 2a: compile free-text product rules into structured checks.
//
// Input: products whose extra_criteria_text changed since it was last compiled
// (usually none, so no LLM call is made). All of them go into ONE Gemini request:
// the LLM translates rules once per product, never once per user.

const MODEL = 'gemini-2.5-flash';

const products = $input.all().map((i) => i.json).filter((p) => p.product_id);
if (products.length === 0) {
  return [{ json: { count: 0 } }];
}

const EMPLOYMENT = ['salaried', 'self_employed', 'business'];
const UNKNOWN_DATA = [
  'employer_category', 'city', 'business_vintage', 'business_turnover',
  'professional_qualification', 'tax_returns', 'other',
];

// Gemini structured output: the response must match this schema exactly.
const requirement = {
  type: 'OBJECT',
  properties: {
    credit_score_min: { type: 'INTEGER', nullable: true },
    monthly_income_min: { type: 'NUMBER', nullable: true },
    age_min: { type: 'INTEGER', nullable: true },
    age_max: { type: 'INTEGER', nullable: true },
    employment_in: { type: 'ARRAY', items: { type: 'STRING', enum: EMPLOYMENT }, nullable: true },
  },
};
const responseSchema = {
  type: 'ARRAY',
  items: {
    type: 'OBJECT',
    properties: {
      product_id: { type: 'INTEGER' },
      kind: { type: 'STRING', enum: ['eligibility', 'informational'] },
      require: requirement,
      conditions: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            when_employment_in: { type: 'ARRAY', items: { type: 'STRING', enum: EMPLOYMENT } },
            require: requirement,
            needs_unknown_data: { type: 'ARRAY', items: { type: 'STRING', enum: UNKNOWN_DATA } },
            verification_note: { type: 'STRING' },
          },
          required: ['when_employment_in', 'require', 'needs_unknown_data', 'verification_note'],
        },
      },
      needs_unknown_data: { type: 'ARRAY', items: { type: 'STRING', enum: UNKNOWN_DATA } },
      verification_note: { type: 'STRING' },
    },
    required: ['product_id', 'kind', 'require', 'conditions', 'needs_unknown_data', 'verification_note'],
  },
};

const instructions = `You translate the free-text eligibility rules of Indian loan products into machine-checkable JSON.

The ONLY applicant facts available are:
- monthly_income (INR per month)
- credit_score (300-900)
- age (years)
- employment_status: one of salaried, self_employed, business

For each product return one object:
- product_id: copied from the input.
- kind: "eligibility" if the text can exclude an applicant; "informational" if it only describes pricing, loan limits or preferences and never excludes anyone.
- require: requirements for every applicant, using only these fields: credit_score_min, monthly_income_min, age_min, age_max, employment_in. Use null for fields the text does not set.
- needs_unknown_data: facts that EVERY applicant must have verified and that are NOT in the applicant data (e.g. employer type, city, years in business, turnover, qualification, tax returns). Empty if none.
- verification_note: one short sentence for the applicant saying what the lender will verify for every applicant, or "" if nothing.
- conditions: rules that apply only to some employment types, as [{"when_employment_in": [...], "require": {...}, "needs_unknown_data": [...], "verification_note": "..."}]. Put a fact here, not at the top level, when the text says it applies only to those applicants.

Rules:
- Never invent thresholds or restrictions that the text does not state.
- Only set employment_in when the text explicitly limits who may apply by employment type (for example "only salaried applicants"). Describing a business, such as its age or turnover, is not by itself an employment restriction.
- "Age at loan maturity must not exceed X" with a minimum tenure of T years means age_max = X - T.
- A threshold that depends on an unknown fact (e.g. a higher income needed in metro cities) must not go into require; list the fact in needs_unknown_data instead.
- Amounts like "Rs 25,000", "25k", "1 lakh" (= 100000) are INR.

Products:
${JSON.stringify(products.map((p) => ({
  product_id: p.product_id,
  product_name: p.product_name,
  rule_text: p.extra_criteria_text,
})), null, 2)}`;

return [{
  json: {
    count: products.length,
    model: MODEL,
    // Remember which text each compile result belongs to (md5 from SQL).
    text_hashes: Object.fromEntries(products.map((p) => [p.product_id, p.text_hash])),
    request_body: {
      contents: [{ role: 'user', parts: [{ text: instructions }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema,
      },
    },
  },
}];

// Stage 2b: validate Gemini's compiled rules before trusting them.
//
// Every field is checked against the allowed names and ranges. A product whose
// result is malformed is stored as status "invalid" (its matches are then flagged
// UNVERIFIED rather than guessed). If the LLM call itself failed, nothing is
// stored, so the next run retries the compile.

const request = $('Build compile request').first().json;
const response = $input.first().json;

const EMPLOYMENT = new Set(['salaried', 'self_employed', 'business']);
const UNKNOWN_DATA = new Set([
  'employer_category', 'city', 'business_vintage', 'business_turnover',
  'professional_qualification', 'tax_returns', 'other',
]);
const LIMITS = {
  credit_score_min: [300, 900],
  monthly_income_min: [0, 100000000],
  age_min: [18, 100],
  age_max: [18, 100],
};

// Postgres string literal; standard_conforming_strings is on, so doubling ' is enough.
const sqlLiteral = (value) => `'${JSON.stringify(value).replace(/'/g, "''")}'`;

function cleanRequirement(raw) {
  if (raw == null) return {};
  if (typeof raw !== 'object' || Array.isArray(raw)) throw new Error('require must be an object');
  const out = {};
  for (const [key, [lo, hi]] of Object.entries(LIMITS)) {
    const v = raw[key];
    if (v == null) continue;
    if (typeof v !== 'number' || !Number.isFinite(v) || v < lo || v > hi) {
      throw new Error(`${key} out of range: ${v}`);
    }
    out[key] = v;
  }
  if (raw.employment_in != null) {
    if (!Array.isArray(raw.employment_in) || !raw.employment_in.every((e) => EMPLOYMENT.has(e))) {
      throw new Error('employment_in has unknown values');
    }
    if (raw.employment_in.length) out.employment_in = raw.employment_in;
  }
  return out;
}

function cleanUnknown(raw) {
  const unknown = raw ?? [];
  if (!Array.isArray(unknown) || !unknown.every((u) => UNKNOWN_DATA.has(u))) {
    throw new Error('needs_unknown_data has unknown values');
  }
  return unknown;
}

const cleanNote = (raw) => String(raw ?? '').slice(0, 300);

function compile(raw) {
  if (!['eligibility', 'informational'].includes(raw.kind)) throw new Error(`bad kind ${raw.kind}`);
  const conditions = (raw.conditions ?? []).map((c) => {
    const when = c.when_employment_in;
    if (!Array.isArray(when) || when.length === 0 || !when.every((e) => EMPLOYMENT.has(e))) {
      throw new Error('condition has bad when_employment_in');
    }
    return {
      when_employment_in: when,
      require: cleanRequirement(c.require),
      needs_unknown_data: cleanUnknown(c.needs_unknown_data),
      verification_note: cleanNote(c.verification_note),
    };
  });
  return {
    status: 'ok',
    kind: raw.kind,
    require: cleanRequirement(raw.require),
    conditions,
    needs_unknown_data: cleanUnknown(raw.needs_unknown_data),
    verification_note: cleanNote(raw.verification_note),
  };
}

const text = response?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  const reason = response?.error?.message ?? response?.error ?? 'no candidates in response';
  return [{ json: { llm_ok: false, error: String(reason).slice(0, 500), saved: 0, sql_payload: "'[]'" } }];
}

let results;
try {
  results = JSON.parse(text);
  if (!Array.isArray(results)) throw new Error('response is not an array');
} catch (e) {
  return [{ json: { llm_ok: false, error: `unparseable LLM output: ${e.message}`, saved: 0, sql_payload: "'[]'" } }];
}

const byId = new Map(results.map((r) => [Number(r?.product_id), r]));
const rows = [];
const problems = [];
for (const [productId, textHash] of Object.entries(request.text_hashes)) {
  const raw = byId.get(Number(productId));
  let compiled;
  try {
    if (!raw) throw new Error('missing from LLM output');
    compiled = compile(raw);
  } catch (e) {
    compiled = { status: 'invalid', reason: e.message };
    problems.push(`product ${productId}: ${e.message}`);
  }
  rows.push({ product_id: Number(productId), text_hash: textHash, compiled });
}

return [{
  json: {
    llm_ok: true,
    saved: rows.filter((r) => r.compiled.status === 'ok').length,
    invalid: problems,
    compiled_rules: rows,
    sql_payload: sqlLiteral(rows),
  },
}];

// Stages 1-4 as ONE statement that runs inside Postgres.
//
// n8n stays the place where matching is decided: this node turns each product's
// compiled rule (stage 2 output), the scoring formula and the top-K cut into
// SQL. Postgres then runs it where the data lives, so 10,000 users and ~43,000
// match rows never travel to n8n and back; only this statement (a few KB) and
// one row of funnel counts do. Measured before this change: 70 of 74 seconds
// were spent shipping rows between n8n and a remote RDS.
//
// Safety: the SQL is assembled only from validated numbers, a fixed set of
// keywords (employment types, facts to verify) and escaped string literals.

const TOP_K = 5;

const batchId = $('Validate request').first().json.batch_id;
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(batchId)) {
  throw new Error(`refusing to build SQL for batch id ${batchId}`);
}
const products = $input.all().map((i) => i.json).filter((p) => Number.isInteger(p.product_id));

const EMPLOYMENT = new Set(['salaried', 'self_employed', 'business']);
const UNKNOWN_DATA = new Set([
  'employer_category', 'city', 'business_vintage', 'business_turnover',
  'professional_qualification', 'tax_returns', 'other', 'text_rule_not_checked',
]);

const text = (v) => `'${String(v).replace(/'/g, "''")}'`;
const num = (v) => {
  const n = Number(v);
  if (!Number.isFinite(n)) throw new Error(`not a number: ${v}`);
  return String(n);
};
const list = (values, allowed) => {
  const ok = (values ?? []).filter((v) => allowed.has(v));
  return ok.length ? `ARRAY[${ok.map(text).join(', ')}]::text[]` : `'{}'::text[]`;
};
const inEmployment = (values) => `u.employment_status IN (${values.filter((v) => EMPLOYMENT.has(v)).map(text).join(', ') || 'NULL'})`;

// One compiled requirement -> SQL boolean (same checks as the old JS `meets`).
function meets(req = {}) {
  const parts = [];
  if (req.credit_score_min != null) parts.push(`u.credit_score >= ${num(req.credit_score_min)}`);
  if (req.monthly_income_min != null) parts.push(`u.monthly_income >= ${num(req.monthly_income_min)}`);
  if (req.age_min != null) parts.push(`u.age >= ${num(req.age_min)}`);
  if (req.age_max != null) parts.push(`u.age <= ${num(req.age_max)}`);
  if (req.employment_in?.length) parts.push(inEmployment(req.employment_in));
  return parts.length ? parts.join(' AND ') : 'TRUE';
}

// Per product: does the pair pass, which stage decided it, what must be verified, and the note.
function judge(p) {
  if (!p.extra_criteria_text) {
    return { pass: 'TRUE', stage: text('HARD_RULES'), verify: `'{}'::text[]`, note: 'NULL::text' };
  }
  const rule = p.compiled_current ? p.compiled_rules : null;
  if (rule?.status !== 'ok') {
    // No usable compiled rule: keep the match, say plainly it was not checked.
    return {
      pass: 'TRUE',
      stage: text('UNVERIFIED'),
      verify: list(['text_rule_not_checked'], UNKNOWN_DATA),
      note: text(`Additional conditions apply: ${p.extra_criteria_text}`),
    };
  }
  if (rule.kind === 'informational') {
    return { pass: 'TRUE', stage: text('COMPILED_RULES'), verify: `'{}'::text[]`, note: 'NULL::text' };
  }
  const conditions = rule.conditions ?? [];
  const pass = [`(${meets(rule.require)})`]
    .concat(conditions.map((c) => `(NOT ${inEmployment(c.when_employment_in)} OR (${meets(c.require)}))`))
    .join(' AND ');

  const top = (rule.needs_unknown_data ?? []).filter((v) => UNKNOWN_DATA.has(v));
  const verifyParts = [list(top, UNKNOWN_DATA)];
  const noteParts = [];
  if (top.length && rule.verification_note) noteParts.push(text(rule.verification_note));
  for (const c of conditions) {
    const extra = (c.needs_unknown_data ?? []).filter((v) => UNKNOWN_DATA.has(v));
    if (!extra.length) continue;
    verifyParts.push(`CASE WHEN ${inEmployment(c.when_employment_in)} THEN ${list(extra, UNKNOWN_DATA)} ELSE '{}'::text[] END`);
    if (c.verification_note) {
      noteParts.push(`CASE WHEN ${inEmployment(c.when_employment_in)} THEN ${text(c.verification_note)} END`);
    }
  }
  return {
    pass,
    stage: text('COMPILED_RULES'),
    // Duplicates removed in SQL, like the JS Set it replaces.
    verify: `ARRAY(SELECT DISTINCT unnest(${verifyParts.join(' || ')}))`,
    note: noteParts.length ? `NULLIF(concat_ws(' ', ${noteParts.join(', ')}), '')` : 'NULL::text',
  };
}

const judged = products.map((p) => ({ id: p.product_id, ...judge(p) }));
const caseOf = (field, fallback) =>
  `CASE u.product_id\n${judged.map((j) => `      WHEN ${j.id} THEN ${j[field]}`).join('\n')}\n      ELSE ${fallback} END`;

const sql = `
WITH cand AS (
  -- Stage 1: hard rules, set-based, scoped to this batch
  SELECT u.user_id, u.employment_status, u.monthly_income, u.credit_score, u.age,
         p.product_id, p.min_credit_score, p.min_monthly_income, p.interest_rate_min
    FROM users u
    JOIN loan_products p
      ON p.is_active
     AND u.monthly_income >= COALESCE(p.min_monthly_income, 0)
     AND u.credit_score   >= COALESCE(p.min_credit_score, 300)
     AND (p.max_credit_score IS NULL OR u.credit_score <= p.max_credit_score)
     AND u.age BETWEEN COALESCE(p.min_age, 18) AND COALESCE(p.max_age, 100)
     AND (p.allowed_employment IS NULL OR u.employment_status = ANY (p.allowed_employment))
   WHERE u.batch_id = '${batchId}'::uuid
), judged AS (
  -- Stage 2: each product's compiled text rule, generated by n8n
  SELECT u.*,
    ${caseOf('pass', 'TRUE')} AS pass,
    ${caseOf('stage', text('HARD_RULES'))} AS stage,
    ${caseOf('verify', `'{}'::text[]`)} AS verify,
    ${caseOf('note', 'NULL::text')} AS note
  FROM cand u
), scored AS (
  -- Stage 3: score 0-100 (credit headroom 40, income headroom 30, rate 20, nothing to verify 10).
  -- CASE, not COALESCE(LEAST(...)): LEAST/GREATEST ignore NULLs in Postgres.
  SELECT j.*, round((
      40 * (CASE WHEN COALESCE(j.min_credit_score, 0) = 0 THEN 0.5
                 ELSE LEAST(1, (j.credit_score - j.min_credit_score) / 100.0) END)
    + 30 * (CASE WHEN COALESCE(j.min_monthly_income, 0) = 0 THEN 0.5
                 ELSE LEAST(1, j.monthly_income / j.min_monthly_income - 1) END)
    + 20 * (CASE WHEN j.interest_rate_min IS NULL THEN 0.5
                 ELSE GREATEST(0, LEAST(1, (36 - j.interest_rate_min) / 26.0)) END)
    + 10 * (CASE WHEN cardinality(j.verify) = 0 THEN 1 ELSE 0 END)
  )::numeric, 2) AS score
  FROM judged j
  WHERE j.pass
), ranked AS (
  -- Stage 4: keep the top ${TOP_K} per user
  SELECT s.*, row_number() OVER (PARTITION BY s.user_id ORDER BY s.score DESC, s.product_id) AS rank
  FROM scored s
), ins AS (
  INSERT INTO matches (user_id, product_id, batch_id, match_stage, score, needs_verification, match_note)
  SELECT user_id, product_id, '${batchId}'::uuid, stage, score, verify, note
    FROM ranked WHERE rank <= ${TOP_K}
  ON CONFLICT (user_id, product_id) DO UPDATE
     SET batch_id = EXCLUDED.batch_id, match_stage = EXCLUDED.match_stage, score = EXCLUDED.score,
         needs_verification = EXCLUDED.needs_verification, match_note = EXCLUDED.match_note
   WHERE NOT matches.notified           -- never touch a match that was already emailed
  RETURNING 1
)
SELECT
  (SELECT count(*) FROM cand)::int                                        AS sql_candidates,
  (SELECT count(*) FROM judged WHERE stage = 'HARD_RULES')::int           AS hard_rule_only,
  (SELECT count(*) FROM judged WHERE stage <> 'HARD_RULES')::int          AS text_rule_pairs,
  (SELECT count(*) FROM judged WHERE NOT pass)::int                       AS text_rule_rejected,
  (SELECT count(*) FROM judged WHERE stage = 'UNVERIFIED')::int           AS unverified_pairs,
  (SELECT count(*) FROM ranked WHERE rank <= ${TOP_K})::int               AS after_top_k,
  (SELECT count(DISTINCT user_id) FROM ranked WHERE rank <= ${TOP_K})::int AS matched_users,
  (SELECT count(*) FROM ins)::int                                         AS matches_inserted;
`;

return [{
  json: {
    batch_id: batchId,
    products_planned: judged.length,
    text_rule_products: products.filter((p) => p.extra_criteria_text).length,
    sql_chars: sql.length,
    sql,
  },
}];

// Stage 5: assemble the funnel report for match_runs and the execution log.

const request = $('Validate request').first().json;
const start = $('Start run').first().json;
const stats = $input.first().json; // one row of counts from "Run matching in database"
const inserted = Number(stats.matches_inserted ?? 0);

let rulesCompiled = 0;
let llmCalls = 0;
let llmError = null;
const compileRequest = $('Build compile request').first().json;
if (compileRequest.count > 0) {
  llmCalls = 1;
  const parsed = $('Parse compiled rules').first().json;
  rulesCompiled = parsed.saved ?? 0;
  llmError = parsed.llm_ok ? null : parsed.error;
}

const funnel = {
  batch_id: request.batch_id,
  users_in_batch: Number(start.users_in_batch),
  active_products: Number(start.active_products),
  raw_pairs: Number(start.users_in_batch) * Number(start.active_products),
  sql_candidates: stats.sql_candidates,
  hard_rule_only: stats.hard_rule_only,
  text_rule_pairs: stats.text_rule_pairs,
  text_rule_rejected: stats.text_rule_rejected,
  unverified_pairs: stats.unverified_pairs,
  after_top_k: stats.after_top_k,
  matched_users: stats.matched_users,
  rules_compiled: rulesCompiled,
  llm_calls: llmCalls,
  matches_inserted: inserted,
  duration_ms: Date.now() - request.started_at,
  llm_error: llmError,
};

return [{ json: funnel }];
